# ================================================================ part 3
# Starts right after the five terms, with no divider slide: first the recording routine, then many transactions, click by click.
opener(3, 'תיעוד עסקאות: סיבה ותוצאה, מקור ושימוש', 'שאלת החלק: מה קורה לנכסים, להתחייבויות ולהון העצמי בכל עסקה?',
       ['תרשים זרימה: איך מתעדים', '20 עסקאות, כל אחת בשלוש לחיצות', 'שאלות רב ברירה בין קבוצות העסקאות', 'אז מה זו הכנסה, ומה זו הוצאה'], 50, hidden=True)

S('s-flow', 'איך מתעדים עסקה', 'איך מתעדים עסקה: תרשים זרימה',
  FLOW(['<b>קרה אירוע</b><br>מכרנו, קנינו, לווינו, שילמנו', '<b>הסיבה: המקור</b><br>מאיפה זה בא?', '<b>התוצאה: השימוש</b><br>לאן זה הלך?', '<b>רושמים את שני הצדדים</b><br>כל סעיף במקומו', '<b>בודקים</b><br>השוויון נשמר?'], rv=1)
  + ST(6, '<div class="demo"><b>דוגמה:</b> ' + TX('נטלנו הלוואה של 200,000 ש״ח. המקור: הבנק, כלומר התחייבות $+200,000$. השימוש: הכסף בחשבון, כלומר מזומן $+200,000$.') + '</div>', cls='mt')
  + '<div class="toonr mt">' + PUN('בחשבונאות אין קסמים. כל שקל הגיע מאיפשהו, והלך לאנשהו.', 7) + ST(7, TOON('deal')) + '</div>', kick='חלק 3 · תרשים זרימה')

S('s-src', 'סיבה ותוצאה, מקור ושימוש', 'מתעדים סיבה ותוצאה, מקור ושימוש',
  '<div class="row eq3 top">'
  + DEF('סיבה ותוצאה', 'כל שינוי קרה בגלל משהו. רושמים גם מה קרה וגם למה.', 'יש 200,000 ש״ח במזומן (תוצאה), כי לווינו מהבנק (סיבה).', trm='cause')
  + DEF('מקור', 'מאיפה הגיע הערך: התחייבות גדלה, הון עצמי גדל, או נכס קטן.', 'שילמנו 60,000 ש״ח במזומן: המקור הוא המזומן שקטן.', 1, trm='srcv')
  + DEF('שימוש', 'לאן הלך הערך: נכס גדל, התחייבות קטנה, או הון עצמי קטן.', 'באותם 60,000 ש״ח קנינו מכונה: השימוש הוא המכונה שגדלה.', 2, trm='usev') + '</div>'
  + RULE('בכל עסקה: <b>סך המקורות שווה לסך השימושים.</b>', 3), kick='חלק 3 · הגדרה והדגמה')

S('s-eq', 'משוואת היסוד', 'משוואת היסוד: כל עסקה שומרת עליה',
  '<p class="lead">' + TX('במילים: סך הנכסים שווה לסך ההתחייבויות ועוד ההון העצמי. כך [[fundeq|משוואת היסוד]], ו[[identity|הזהות החשבונאית]] אומרת שהיא נשמרת אחרי כל עסקה.') + '</p>'
  + IDENT([('c-asset', 'סך נכסים', '', '320,000'), '=', ('c-liab', 'סך התחייבויות', '', '148,000'), '+', ('c-eq', 'סך הון עצמי', '(לרבות הכנסות והוצאות)', '172,000')])
  + '<div class="row eq2 top mt">'
  + DEF('רישום דו-צדדי', 'כל עסקה נרשמת לפחות בשני מקומות, כך שהשוויון נשמר.', 'הנפקת מניות ב-100,000 ש״ח: מזומן $+100,000$, הון מניות $+100,000$.', 1, trm='double')
  + DEF('רמת הסעיף', 'מזהים את הסעיף המדויק, ולא רק את הקבוצה. כך גם במטלה ובבחינה.', 'לא ״נכסים $+30,000$״, אלא ״מזומן $+30,000$״.', 2, trm='item') + '</div>'
  + RULE('מכאן והלאה: קוראים את העסקה, חושבים, ורק אז לוחצים. <b>נכסים, התחייבויות, הון עצמי.</b>', 3), kick='חלק 3 · נוסחה')

